import logging

import torch
import triton
import triton.language as tl

from flag_gems.runtime import torch_device_fn

_MAX_GRID_X = 65535  # device grid-dimension limit (Ascend coreDim <= 65535)


logger = logging.getLogger(__name__)


@triton.jit
def _nested_sum_backward_kernel(
    grad_ptr,
    out_ptr,
    outer_size,
    dim_size,
    inner_size,
    D_TILE: tl.constexpr,
    I_TILE: tl.constexpr,
):
    """Broadcast ``grad`` [outer, inner] back to [outer, dim, inner].

    The output is contiguous, so a program owns a ``D_TILE x I_TILE`` rectangle
    of one ``(outer, dim, inner)`` plane and re-stores the same ``grad`` tile to
    every reduced position.  Tiling instead of a flat index keeps the kernel
    free of per-element integer division (which is extremely slow on some
    accelerators) and reads ``grad`` once per rectangle instead of once per
    output element.

    The grid is a flat list of tiles: some backends limit the *total* number of
    programs (not just each grid dimension), so the tiles are enumerated with a
    1-D grid and walked with a grid-stride loop.
    """
    pid = tl.program_id(0)
    n_inner = tl.cdiv(inner_size, I_TILE)
    n_dim = tl.cdiv(dim_size, D_TILE)
    total = outer_size * n_dim * n_inner
    step = tl.num_programs(0)
    d_lanes = tl.arange(0, D_TILE)[:, None]
    i_lanes = tl.arange(0, I_TILE)[None, :]

    tile = pid
    while tile < total:
        i_tile = tile % n_inner
        rest = tile // n_inner
        d_tile = rest % n_dim
        outer = rest // n_dim

        d = d_tile * D_TILE + d_lanes
        inner = i_tile * I_TILE + i_lanes
        i_mask = inner < inner_size
        grad = tl.load(
            grad_ptr + outer * inner_size + inner,
            mask=i_mask,
            other=0,
        )
        # Materialize the [1, I_TILE] row across the reduced positions
        # explicitly: an implicit broadcast on store is not reliable on
        # every backend.
        grad = tl.broadcast_to(grad, (D_TILE, I_TILE))
        out_offset = (outer * dim_size + d) * inner_size + inner
        tl.store(
            out_ptr + out_offset,
            grad,
            mask=(d < dim_size) & i_mask,
        )
        tile += step


@triton.jit
def _nested_sum_backward_lastdim_kernel(
    grad_ptr,
    out_ptr,
    outer_size,
    dim_size,
    R: tl.constexpr,
    C: tl.constexpr,
):
    """Fast path for a reduction over the *last* axis (``inner_size == 1``).

    The output is ``[outer, dim]`` contiguous with row ``o`` filled with
    ``grad[o]``.  Loading ``R`` gradients as a *vector* and broadcasting it down
    the columns of an ``(R, C)`` tile keeps the broadcast on the contiguous
    axis, which the vector unit handles at memory speed; broadcasting a single
    scalar over a ``(dim, 1)`` tile instead degrades to per-element stores
    (measured 1.20 ms -> 0.026 ms for 32768 x 512).
    """
    pid = tl.program_id(0)
    n_col = tl.cdiv(dim_size, C)
    o_block = pid // n_col
    c_block = pid - o_block * n_col
    rows = o_block * R + tl.arange(0, R)
    cols = c_block * C + tl.arange(0, C)
    m_row = rows < outer_size
    m_col = cols < dim_size
    v = tl.load(grad_ptr + rows, mask=m_row, other=0.0)
    val = tl.broadcast_to(v[:, None], (R, C))
    tl.store(
        out_ptr + rows[:, None] * dim_size + cols[None, :],
        val,
        mask=m_row[:, None] & m_col[None, :],
    )


def _nested_sum_backward(grad, self, dim=None, keepdim=False):
    """Backward of the (nested) tensor `sum` over a single dimension.

    Given the gradient `grad` of the summed output, broadcast it back to the
    original `self` shape along the reduced dimension. For regular dense
    tensors this is equivalent to ``grad.expand_as(self)`` after re-inserting
    the reduced dimension when ``keepdim`` is False.

    Args:
        grad (Tensor): the gradient w.r.t. the output of ``sum(dim)``.
        self (Tensor): the original input tensor, providing the output shape.
        dim (Optional[int[1]]): the dimension that was reduced.
        keepdim (bool): whether the reduced dimension was retained in `grad`.

    Returns:
        Tensor: the gradient broadcast back to the shape of `self`.
    """
    logger.debug("GEMS _NESTED_SUM_BACKWARD")

    shape = list(self.shape)
    ndim = self.dim()

    if dim is None:
        # Full reduction: `grad` is a scalar (or an all-ones keepdim shape).
        # Broadcasting a 0-d/1-d tensor to `shape` is a no-data-copy edge case
        # that never occurs for nested tensors (which always reduce a dim).
        return grad.broadcast_to(shape).contiguous()

    if isinstance(dim, (list, tuple)):
        d = int(dim[0])
    else:
        d = int(dim)
    if d < 0:
        d += ndim

    inner_size = 1
    for s in shape[d + 1 :]:
        inner_size *= s
    dim_size = shape[d]

    grad = grad.contiguous()
    out = torch.empty(shape, dtype=grad.dtype, device=grad.device)

    numel = out.numel()
    if numel == 0:
        return out

    outer_size = numel // (dim_size * inner_size)
    if inner_size == 1 and dim_size > 1:
        # Reduction over the last axis: broadcast whole vectors down the
        # contiguous axis of an (R, C) tile (see the kernel docstring).
        r = 64
        c = min(triton.next_power_of_2(dim_size), 512)
        n_row_blocks = triton.cdiv(outer_size, r)
        n_col_blocks = triton.cdiv(dim_size, c)
        grid = (min(n_row_blocks * n_col_blocks, _MAX_GRID_X),)
        with torch_device_fn.device(grad.device):
            _nested_sum_backward_lastdim_kernel.run(
                grad, out, outer_size, dim_size, R=r, C=c, grid=grid, warmup=False
            )
        return out

    # Tile the (dim, inner) plane with a ~1024-element rectangle: when the
    # innermost size is small, several reduced positions share one program;
    # when it is large, the rectangle is one row-slice and the tile loop walks
    # the inner axis.
    _BLOCK = 16384
    i_tile = min(triton.next_power_of_2(max(inner_size, 1)), _BLOCK)
    # Never make a tile wider than the reduced extent: the surplus lanes would
    # be masked off, and when ``dim_size`` is small that is most of the tile
    # (measured 40x slower on a (64, 512) -> (64, 512, 512) broadcast).
    d_tile = max(
        1,
        min(_BLOCK // i_tile, triton.next_power_of_2(max(dim_size, 1))),
    )
    n_tiles = (
        outer_size * triton.cdiv(dim_size, d_tile) * triton.cdiv(inner_size, i_tile)
    )
    grid = (min(n_tiles, _MAX_GRID_X),)
    _nested_sum_backward_kernel.run(
        grad,
        out,
        outer_size,
        dim_size,
        inner_size,
        D_TILE=d_tile,
        I_TILE=i_tile,
        grid=grid,
        warmup=False,
    )
    return out
